// static
bool StructTraits<::ash::libassistant::mojom::AssistantInteractionMetadata::DataView, ::ash::libassistant::mojom::AssistantInteractionMetadataPtr>::Read(
    ::ash::libassistant::mojom::AssistantInteractionMetadata::DataView input,
    ::ash::libassistant::mojom::AssistantInteractionMetadataPtr* output) {
  bool success = true;
  ::ash::libassistant::mojom::AssistantInteractionMetadataPtr result(::ash::libassistant::mojom::AssistantInteractionMetadata::New());
  
      if (success && !input.ReadType(&result->type))
        success = false;
      if (success && !input.ReadSource(&result->source))
        success = false;
      if (success && !input.ReadQuery(&result->query))
        success = false;
  *output = std::move(result);
  return success;
}


// static
bool StructTraits<::ash::libassistant::mojom::AssistantSuggestion::DataView, ::ash::libassistant::mojom::AssistantSuggestionPtr>::Read(
    ::ash::libassistant::mojom::AssistantSuggestion::DataView input,
    ::ash::libassistant::mojom::AssistantSuggestionPtr* output) {
  bool success = true;
  ::ash::libassistant::mojom::AssistantSuggestionPtr result(::ash::libassistant::mojom::AssistantSuggestion::New());
  
      if (success && !input.ReadId(&result->id))
        success = false;
      if (success && !input.ReadType(&result->type))
        success = false;
      if (success && !input.ReadText(&result->text))
        success = false;
      if (success && !input.ReadIconUrl(&result->icon_url))
        success = false;
      if (success && !input.ReadActionUrl(&result->action_url))
        success = false;
  *output = std::move(result);
  return success;
}

